package com.bank.statement;

import java.util.Arrays;
import java.util.logging.*;

public class MoveZeroesDemo {
    private static final Logger log = Logger.getLogger(MoveZeroesDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StatementCompactor compactor = new StatementCompactor();

        // Priya's charges in paise; zeros are cancelled items
        int[] charges = {15000, 0, 32000, 0, 0, 5000, 48000};
        log.info(() -> "Before: " + Arrays.toString(charges));

        compactor.moveZeroes(charges);
        log.info(() -> "After : " + Arrays.toString(charges));
    }
}

