class StatementCompactor {
    private static final Logger log = Logger.getLogger(StatementCompactor.class.getName());

    // Same-direction compaction. Order preserved. O(n) time, O(1) space.
    void moveZeroes(int[] a) {
        int insert = 0; // slow pointer: next slot for a non-zero
        for (int i = 0; i < a.length; i++) {  // fast pointer scans all
            if (a[i] != 0) {
                a[insert++] = a[i];           // keep real charge, preserve order
            }
        }
        int firstZeroAt = insert;
        while (insert < a.length) {
            a[insert++] = 0;                  // pad the tail with cancelled slots
        }
        log.fine(() -> "Non-zero count = " + firstZeroAt);
    }
}

